var _markdown = "\n\n`CPlayerPed.h` · 继承 `CPed`\n\n`FindPlayerPed()` 返回 `CPlayerPed*`。通用 ped API 见 [行人](/docs/plugins/entities/ped)。\n\n## 取通缉 [#取通缉]\n\n<Api name=\"GetWanted / SetWantedLevel / CheatWantedLevel\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      CWanted* GetWanted(); // inline，经 m_pPlayerData\n      int GetWantedLevel();\n      void SetWantedLevel(int level);\n      void SetWantedLevelNoDrop(int level);\n      void CheatWantedLevel(int level);\n      void Busted(); // 星清零路径之一\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      CPlayerPed* pp = FindPlayerPed();\n      if (!pp) {\n          return;\n      }\n      pp->SetWantedLevel(0);\n      // 或 pp->GetWanted()->SetWantedLevel(0);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 取 Pad / PlayerInfo [#取-pad--playerinfo]\n\n<Api name=\"GetPadFromPlayer / GetPlayerInfoForThisPlayerPed\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      CPad* GetPadFromPlayer();\n      CPlayerInfo* GetPlayerInfoForThisPlayerPed();\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      CPad* pad = pp->GetPadFromPlayer();\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 武器目标 [#武器目标]\n\n<Api name=\"ClearWeaponTarget / FindWeaponLockOnTarget\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      void ClearWeaponTarget();\n      bool FindWeaponLockOnTarget();\n      CPed* m_pPlayerTargettedPed;\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      pp->ClearWeaponTarget();\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 换武器表现 [#换武器表现]\n\n<Api name=\"MakeChangesForNewWeapon / ProcessWeaponSwitch\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      void MakeChangesForNewWeapon(eWeaponType weaponType);\n      void MakeChangesForNewWeapon(int weaponSlot);\n      bool DoesPlayerWantNewWeapon(eWeaponType weaponType, bool arg1);\n      void ProcessWeaponSwitch(CPad* pad);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      pp->MakeChangesForNewWeapon(WEAPONTYPE_M4);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 冲刺与呼吸 [#冲刺与呼吸]\n\n<Api name=\"ResetSprintEnergy / ResetPlayerBreath\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      void ResetSprintEnergy();\n      float ControlButtonSprint(eSprintType sprintType);\n      void ResetPlayerBreath();\n      void HandlePlayerBreath(bool arg0, float arg1);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      pp->ResetSprintEnergy();\n      pp->ResetPlayerBreath();\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 小队 [#小队]\n\n<Api name=\"MakeThisPedJoinOurGroup / DisbandPlayerGroup\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      void MakeThisPedJoinOurGroup(CPed* ped);\n      void DisbandPlayerGroup();\n      void TellGroupToStartFollowingPlayer(bool arg0, bool arg1, bool arg2);\n      void ForceGroupToAlwaysFollow(bool enable);\n      void ForceGroupToNeverFollow(bool enable);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // pp->DisbandPlayerGroup();\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 肾上腺素 [#肾上腺素]\n\n<Api name=\"ClearAdrenaline\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      void ClearAdrenaline();\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      pp->ClearAdrenaline();\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 静态玩家生命周期 [#静态玩家生命周期]\n\n<Api name=\"SetupPlayerPed / RemovePlayerPed\">\n  极少直接调。\n\n  ```cpp\n  static void SetupPlayerPed(int playerId);\n  static void RemovePlayerPed(int playerId);\n  static void DeactivatePlayerPed(int playerId);\n  static void ReactivatePlayerPed(int playerId);\n  ```\n</Api>\n";
